import SwiftUI
struct PlanBuilderView:View{@Environment(AppState.self)private var app;@State private var draft=PlanDraft();@State private var search=AddressSearchService();@State private var error:String?;@State private var resolving=false;@State private var builtPlan:ActivityPlan?
 var body:some View{NavigationStack{Form{Section("Who"){Picker("Profile",selection:$draft.profileID){Text("Choose a profile").tag(UUID?.none);ForEach(app.profiles.profiles){Text($0.name).tag(Optional($0.id))}}}Section("What"){TextField("Event or activity name",text:$draft.activityName);Picker("Activity type",selection:$draft.activityType){ForEach(ActivityType.allCases){Text($0.label).tag($0)}}}Section("Where"){TextField("Exact address or place",text:$draft.addressQuery).onChange(of:draft.addressQuery){_,v in if draft.location?.name != v{draft.location=nil;search.search(v)}};if draft.location==nil{ForEach(search.suggestions){s in Button{Task{await select(s)}}label:{VStack(alignment:.leading){Text(s.title);Text(s.subtitle).font(.caption).foregroundStyle(.secondary)}}}};if let l=draft.location{Label(l.formattedAddress.isEmpty ? l.name:l.formattedAddress,systemImage:"mappin.circle.fill").foregroundStyle(.secondary)};if let error{Text(error).foregroundStyle(.red).font(.caption)}}Section("When"){DatePicker("Date",selection:$draft.startTime,displayedComponents:.date);DatePicker("Start time",selection:$draft.startTime,displayedComponents:.hourAndMinute);Stepper("Duration: \(draft.durationMinutes) min",value:$draft.durationMinutes,in:15...480,step:15)}Section("Can the start time change?"){Picker("Flexibility",selection:$draft.flexibility){ForEach(TimeFlexibility.allCases){Text($0.label).tag($0)}}.pickerStyle(.inline);if draft.flexibility == .flexible{DatePicker("Earliest start",selection:Binding(get:{draft.earliestStart ?? draft.startTime.addingTimeInterval(-3600)},set:{draft.earliestStart=$0}),displayedComponents:.hourAndMinute);DatePicker("Latest start",selection:Binding(get:{draft.latestStart ?? draft.startTime.addingTimeInterval(3600)},set:{draft.latestStart=$0}),displayedComponents:.hourAndMinute)}}Section{Button("See Exposure"){build()}.buttonStyle(.borderedProminent).frame(maxWidth:.infinity).disabled(!valid || resolving)}footer:{Text("The app compares modeled exposure. It does not decide whether an activity is medically safe.")}}.navigationTitle("Schedule").navigationDestination(item:$builtPlan){p in ResultsView(plan:p)}.onAppear{if let incoming=app.scheduleDraft{draft=incoming;app.scheduleDraft=nil}else if draft.profileID==nil{draft.profileID=app.profiles.selectedProfileID}}}}
 var valid:Bool{draft.profileID != nil && !draft.activityName.trimmingCharacters(in:.whitespaces).isEmpty && draft.location != nil}
 func select(_ s:LocationSuggestion)async{resolving=true;defer{resolving=false};do{let l=try await search.resolve(s);draft.location=l;draft.addressQuery=l.name;search.suggestions=[]}catch{self.error="We couldn't resolve that place. Try a more complete address."}}
 func build(){guard let p=draft.profileID,let l=draft.location else{return};builtPlan=.init(profileID:p,activityType:draft.activityType,activityName:draft.activityName,location:l,startTime:draft.startTime,durationMinutes:draft.durationMinutes,constraints:.init(timeFlexibility:draft.flexibility,earliestStart:draft.earliestStart,latestStart:draft.latestStart))}
}
